installation.script:
#!/bin/bash
# SRS: SRS publishes Linux builds only as its container image, so this
# takes the server and its web pages (console, players) out of the
# official image on Docker Hub, every layer checked against its SHA-256.
# srs.conf and recordings are never touched once there.
set -euo pipefail
cd /mnt/server
work=/mnt/server/.raptor-build
rm -rf "$work" && mkdir -p "$work"
trap 'rm -rf "$work"' EXIT
fail() { echo "$1"; exit 1; }
ua="raptor-installer (+https://raptorpanel.net)"
get() { curl -fsS --retry 3 -A "$ua" "$@"; }

case "$(uname -m)" in
    x86_64) arch=amd64 ;;
    aarch64) arch=arm64 ;;
    *) fail "SRS has no build for this CPU ($(uname -m))." ;;
esac

# The release, from GitHub (gh-release says why when it doesn't exist);
# the image has the same tag.
version="${VERSION:-latest}"
[ "$version" = latest ] || version="v${version#v}"
tag=$(gh-release tag ossrs/srs "$version") || exit 1

if [ -x objs/srs ] && [ -d objs/nginx/html ] && [ "$(cat .srs-version 2>/dev/null)" = "$tag" ]; then
    echo "SRS $tag is already installed."
else
    echo "Downloading SRS $tag"
    repo=ossrs/srs
    reg=https://registry-1.docker.io/v2/$repo
    token=$(get "https://auth.docker.io/token?service=registry.docker.io&scope=repository:$repo:pull" | jq -r .token) ||
        fail "Docker Hub can't be reached right now. Reinstall to try again."
    auth="Authorization: Bearer $token"
    index=$(get -H "$auth" -H "Accept: application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.list.v2+json" "$reg/manifests/$tag") ||
        fail "SRS's image for $tag isn't on Docker Hub. Set Version to latest, or to another release, then reinstall."
    digest=$(jq -r --arg a "$arch" 'first(.manifests[] | select(.platform.os == "linux" and .platform.architecture == $a) | .digest) // empty' <<<"$index")
    [ -n "$digest" ] || fail "SRS $tag has no image for this CPU ($arch)."
    layers=$(get -H "$auth" -H "Accept: application/vnd.oci.image.manifest.v1+json, application/vnd.docker.distribution.manifest.v2+json" "$reg/manifests/$digest" | jq -r '.layers[].digest') ||
        fail "Docker Hub can't be reached right now. Reinstall to try again."
    mkdir -p "$work/root"
    for layer in $layers; do
        get -L -H "$auth" -o "$work/layer" "$reg/blobs/$layer" || fail "The download failed. Reinstall to try again."
        [ "sha256:$(sha256sum "$work/layer" | cut -d' ' -f1)" = "$layer" ] || fail "The download didn't match its checksum. Reinstall to try again."
        # Only SRS's own folder: the rest is the image's operating system.
        tar -xf "$work/layer" -C "$work/root" --no-same-owner --wildcards 'usr/local/srs/*' 2>/dev/null || true
        rm -f "$work/layer"
    done
    new="$work/root/usr/local/srs/objs"
    [ -x "$new/srs" ] && [ -f "$new/nginx/html/index.html" ] || fail "SRS's image didn't have the files it should. Reinstall to try again."
    mkdir -p objs
    install -m 0755 "$new/srs" objs/srs.new
    rm -rf objs/nginx.old
    [ ! -d objs/nginx ] || mv objs/nginx objs/nginx.old
    mv "$new/nginx" objs/nginx
    mv -f objs/srs.new objs/srs
    rm -rf objs/nginx.old
    echo "$tag" > .srs-version
fi

# A first configuration. Ports, the HTTP API's login and WebRTC's address
# come from the server's settings at every start (SRS_* environment
# variables win over this file); who may publish is written to
# .raptor-security.conf at every start.
if [ ! -f srs.conf ]; then
    cat > srs.conf <<'CONF'
# SRS's settings: https://ossrs.net/lts/en-us/docs/v6/doc/getting-started
# Restart the server after changing this file.
listen              1935;
max_connections     1000;
srs_log_tank        console;
daemon              off;
query_latest_version off;

http_api {
    enabled         off;
    listen          1985;
}
http_server {
    enabled         on;
    listen          8080;
    dir             ./objs/nginx/html;
}
rtc_server {
    enabled         on;
    listen          8000;
}
vhost __defaultVhost__ {
    include ./.raptor-security.conf;
    hls {
        enabled         on;
        hls_path        ./objs/nginx/html;
    }
    http_remux {
        enabled     on;
        mount       [vhost]/[app]/[stream].flv;
    }
    rtc {
        enabled     on;
        rtmp_to_rtc on;
        rtc_to_rtmp on;
    }
}
CONF
    echo "Wrote a first configuration to srs.conf."
fi
echo "Installed SRS $tag."
